ns16:scriptTask.ns16:script:
 tw.local.errorMessage ="";
 var mandatoryTriggered = false;

/************************************************************************************************************************
/*-------------------------------------------------- All Section's Validation ------------------------------------------
************************************************************************************************************************/
//-------------------------------------------------DC TEMPLATE VALIDATION -------------------------------------------
mandatory(tw.local.odcRequest.stepLog.action, "tw.local.odcRequest.stepLog.action");

maxLength(tw.local.odcRequest.stepLog.comment , "tw.local.odcRequest.stepLog.comment",500 , "Shouldn't be more than 500 character" , " Comment :" + "Shouldn't be more than 500 character" );

if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToMaker)
{
	mandatory(tw.local.odcRequest.stepLog.returnReason, "tw.local.odcRequest.stepLog.returnReason");
	maxLength(tw.local.odcRequest.stepLog.returnReason , "tw.local.odcRequest.stepLog.returnReason" , 80 , "Shouldn't be more than 80 characters" , "Return reason :- This field shouldn't be more than 80 character");
}	

if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.terminateRequest)
{
	mandatory(tw.local.odcRequest.stepLog.terminateReason, "tw.local.odcRequest.stepLog.terminateReason");
	maxLength(tw.local.odcRequest.stepLog.terminateReason , "tw.local.odcRequest.stepLog.terminateReason" , 80 , "Shouldn't be more than 80 characters" , "Termination reason :- This field shouldn't be more than 80 character");
}	
if (tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToTradeFo || tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToInitiator )
{
	mandatory(tw.local.odcRequest.stepLog.returnReason, "tw.local.odcRequest.stepLog.returnReason");
	maxLength(tw.local.odcRequest.stepLog.returnReason , "tw.local.odcRequest.stepLog.returnReason" , 80 , "Shouldn't be more than 80 characters" , "Return reason :- This field shouldn't be more than 80 character");
}
/************************************************************************************************************************
/*-------------------------------------------------- Validation Functions ------------------------------------------
************************************************************************************************************************/
/*
* =========================================================================================================
*  
* Add a coach validation error 
* 		
* EX:	addError(tw.local.name , 'this is a control validation message!' , 'this is a validation message!');
*
* =========================================================================================================
*/
function addError(fieldName , controlMessage , validationMessage , fromMandatory)
{
	tw.system.coachValidation.addValidationError(fieldName, controlMessage);
	fromMandatory && mandatoryTriggered ? "" : tw.local.errorMessage += "<li>" + validationMessage + "</li>";
}
/*
* =================================================================================================================================
*
* Add a coach validation error if the string length is less than given length
*	
* EX:	minLength(tw.local.name , 'tw.local.name' , 10 , 'this is a control validation message!' , 'this is a validation message!')
*
* =================================================================================================================================
*/

function minLength(field , fieldName , len , controlMessage , validationMessage)
{
	if (field != null && field != undefined && field.length < len)
	{
		addError(fieldName , controlMessage , validationMessage);
		return false;
	}
	return true;
}
/*
* =======================================================================================================================
*
* Add a coach validation error if the string length is greater than given length
*	
* EX:	maxLength(tw.local.name , 'tw.local.name' , 14 , 'this is a validation message!' , 'this is a validation message!')
*
* =======================================================================================================================
*/
function maxLength(field , fieldName , len , controlMessage , validationMessage)
{
	if (field.length > len)
	{
		addError(fieldName , controlMessage , validationMessage);
		return false;
	}
	return true;
}
/*
* ==================================================================================================================
*
* Add a coach validation error if the field is null 'Mandatory'
*	
* EX:	notNull(tw.local.name , 'tw.local.name')
*
* ==================================================================================================================
*/

function mandatory(field , fieldName)
{
	if (field == null || field == undefined )
	{
		addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
		mandatoryTriggered = true;
		return false;
	}
	else
	{			
		switch (typeof field)
		{
			case "string":
				if (field.trim() != undefined && field.trim() != null && field.trim().length == 0)
				{
					addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
					mandatoryTriggered = true;
					return false;
				}
				break;
			case "number":
				if (field == 0.0)
				{
					addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
					mandatoryTriggered = true;
					return false;
				}
				break;
	
			default:
				
				// VALIDATE DATE OBJECT
				if( field && field.getTime && isFinite(field.getTime()) ) {}
				
				else
				{
					addError(fieldName , tw.resource.ValidationMessages.ThisFieldIsMandatory , tw.resource.ValidationMessages.MandatoryFields , true);
					mandatoryTriggered = true;
					return false;	
				}
		}
	}
	return true;
}

	tw.local.errorMessage ="";
	tw.local.errorMessage!="" ?  tw.local.errorPanelVIS ="EDITABLE": tw.local.errorPanelVIS ="NONE";

tw.local.odcRequest.stepLog = {};
tw.local.odcRequest.stepLog.startTime = new Date();
tw.local.odcRequest.stepLog.step =tw.epv.ScreenNames.CACT05;
tw.local.odcRequest.appInfo.stepName = ""+tw.epv.ScreenNames.CACT05;

tw.local.actionConditions = {};
tw.local.actionConditions.complianceApproval= tw.local.odcRequest.complianceApproval;
tw.local.actionConditions.screenName= tw.epv.ScreenNames.CACT05;
tw.local.actionConditions.userRole= tw.local.odcRequest.initiator;
tw.local.actionConditions.lastStepAction= tw.local.lastAction;

if(tw.local.lastAction != tw.epv.CreationActions.terminateRequest)
	tw.local.terminationReasonVIS ="None";
else
	tw.local.terminationReasonVIS ="Editable";


tw.local.deliveryTerms = tw.epv.TermsAndConditions.deliveryTerms;
tw.local.paymentTerms = tw.epv.TermsAndConditions.paymentTerms;
tw.local.specialInstructions = tw.epv.TermsAndConditions.specialInstructions;
tw.local.instructions = tw.epv.TermsAndConditions.instructions;

/*Visibilty Conditions*/
/*Basic Details CV Visibility*/
///////////////////////////////
//Parent Request Number
if(tw.local.odcRequest.requestNature.value == tw.epv.RequestNature.UpdateRequest){
	tw.local.parentRequestNoVIS = "Readonly";
}	
else{
	tw.local.parentRequestNoVIS = "None";
}	
//Contract Stage
if(tw.local.odcRequest.requestType.value == tw.epv.RequestType.Create ||tw.local.odcRequest.BasicDetails.requestType == tw.epv.RequestType.Recreate  || tw.local.odcRequest.BasicDetails.requestType == tw.epv.RequestType.Amendment){
	tw.local.contractStageVIS = "READONLY";
}
else{
tw.local.contractStageVIS = "NONE";
}
/*Document Generation Section*/
///////////////////////////////
if(tw.local.odcRequest.requestType.value == tw.epv.RequestType.Amendment || tw.local.odcRequest.requestType.value == tw.epv.RequestType.Recreate){
	tw.local.requestTypeVIS = "READONLY";
}
else{
	tw.local.requestTypeVIS = "NONE";	
}
/*Importer Details Visibility*/
if(tw.local.odcRequest.requestType.value == tw.epv.RequestType.Amendment || tw.local.odcRequest.requestType.value == tw.epv.RequestType.Recreate){
	tw.local.bankRefVIS = "READONLY";
}
else{
	tw.local.bankRefVIS = "NONE";	
}
/* Financial Detais Trade Fo*/
if(tw.local.odcRequest.BasicDetails.paymentTerms.name == "004")
{
	tw.local.multiTenorDatesVIS = "Readonly";
}
else
{
	tw.local.multiTenorDatesVIS = "None";
}

tw.local.errorPanelVIS="NONE";
tw.local.odcRequest.ContractCreation.baseDate = tw.local.contractCreationDate;
//=====================================================================================

if(tw.local.lastAction == tw.epv.CreationActions.submitRequestToHubDirectly)
{
	tw.local.executionSectionVIS = "None";
	
}
else
{
	tw.local.executionSectionVIS = "Readonly";
}
tw.local.requestTypeRecreate = ""+tw.epv.RequestType.Recreate;
tw.local.requestAmend = "" + tw.epv.RequestType.Amendment;

/*
var newSel = [];
var index =0;

if(!!tw.local.odcRequest.FcCollections.selectedTransactions){

	for(var i =0; i<tw.local.odcRequest.FcCollections.selectedTransactions.length; i++){
		if(tw.local.odcRequest.FcCollections.selectedTransactions[i].changeOperation == "D")
			continue;
		else{
			newSel[index] = {};
			newSel[index] = tw.local.odcRequest.FcCollections.selectedTransactions[i];
			index++;
		}
			
	}
	tw.local.odcRequest.FcCollections.selectedTransactions = newSel;
}*/

tw.local.futureDate = new Date();
tw.local.futureDate.setDate(tw.local.futureDate.getDate() +2 );
tw.local.negotiatedExchangeRateVis="READONLY";

if(tw.local.statues!="Success" && !!tw.local.statues)
{

	tw.local.RPAmassage = "Failed RPA with message : " + tw.local.ErrorMassageRPA;
	tw.local.RPAvis = "Readonly";
}
else{
	tw.local.RPAvis = "none";
}
tw.local.terminate = false;

if(tw.local.odcRequest.stepLog.action      == tw.epv.CreationActions.authorize)
{
	var isAmendOrRecreate = tw.local.odcRequest.requestType.value == tw.epv.RequestType.Amendment ||tw.local.odcRequest.requestType.value == tw.epv.RequestType.Recreate;
	var isRegen = tw.local.odcRequest.GeneratedDocumentInfo.regenerateRemLetter == true;
	if(tw.local.odcRequest.requestType.value == tw.epv.RequestType.Create ) {
		
	tw.local.odcRequest.appInfo.status    ="" + tw.epv.Status.completed;
	tw.local.odcRequest.appInfo.subStatus = ""+ tw.epv.Status.PendingPrintingDocumentsforCustomer;
//	console.log("create");
	}
	
	else if( isAmendOrRecreate && isRegen )
	{
	tw.local.odcRequest.appInfo.status    ="" + tw.epv.Status.completed;
	tw.local.odcRequest.appInfo.subStatus = ""+ tw.epv.Status.PendingPrintingDocumentsforCustomer;
//	console.log("create");
	}
	else
	{
		tw.local.odcRequest.appInfo.status    = "" + tw.epv.Status.completed;
		tw.local.odcRequest.appInfo.subStatus = "" + tw.epv.Status.completed;
//		console.log("else");
	}
	tw.local.odcRequest.BasicDetails.requestState = ""+ tw.epv.RequestState.Final;
}
else if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToMaker){
	tw.local.odcRequest.appInfo.status    = "" + tw.epv.Status.InExecution;
	tw.local.odcRequest.appInfo.subStatus = "" + tw.epv.Status.PendingExecutionHubInitiation;
}
else if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToInitiator){
	tw.local.odcRequest.appInfo.status    = "" + tw.epv.Status.initiated;
	tw.local.odcRequest.appInfo.subStatus = "" + tw.epv.Status.returnToInitiator;
}
else if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.returnToTradeFo){
	tw.local.odcRequest.appInfo.status    = "" + tw.epv.Status.InApproval;
	tw.local.odcRequest.appInfo.subStatus = "" + tw.epv.Status.PendingTradeFoReview;
}
else if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.obtainApprovals){
	tw.local.odcRequest.appInfo.status    = "" + tw.epv.Status.InExecution;
	tw.local.odcRequest.appInfo.subStatus = "" + tw.epv.Status.PendingExecutionHubProcessing;
}

else if(tw.local.odcRequest.stepLog.action == tw.epv.CreationActions.terminateRequest){
	tw.local.odcRequest.appInfo.status    = ""+tw.epv.Status.terminated;
	tw.local.odcRequest.appInfo.subStatus = ""+tw.epv.Status.terminated;
	tw.local.terminate = true;
}

tw.local.lastAction ="";

tw.local.alertMessage = String(tw.error.data);
tw.local.errorVis = "EDITABLE";
tw.local.errorPanelVIS = "Editable";
tw.local.errorMessage = tw.local.alertMessage;
